211     func validateNestScopeAction(_ action: Selector) -> Bool? {
212         // The MARKER commands are off inside a nest, and this is more than
213         // the polish the road map called it. A nest has no `markers[]`, so
214         // the core refuses all three marker ops with a scope by name; and the
215         // app's own answer — send them unscoped, the way it sends `add_media`
216         // (`ReelOp.isDocumentLevel`) — is wrong for a different reason, since
217         // the playhead inside a nest is measured from the NEST's zero and a
218         // marker written at that tick would land at the wrong project time.
219         // So they are refused rather than re-based: a marker is a chapter
220         // point on the exported file, and the file is the timeline's.
221         //
222         // This arm runs BEFORE `validateTimelineAction`'s in the base file's
223         // chain, which is what lets it override an answer that file gives.
224         if document?.scope != nil, Self.markerActions.contains(action) { return false }
225         // And BOTH scope items are dead while text is being edited, which is
226         // the bare ⌫'s rule (`EditorViewController+Timeline.swift`) applied
227         // to a pair that carries a modifier — because the modifier buys
228         // nothing here. `NSApplication.sendEvent` offers every main-menu key
229         // equivalent the key-down BEFORE the window dispatches it to the
230         // first responder; what ⌘ changes is only WHICH field-editor binding
231         // is displaced, and ⌘↑ / ⌘↓ are `moveToBeginningOfDocument:` and
232         // `moveToEndOfDocument:`. So a live item would take them from an
233         // inline rename, the Clip tab's name field and the timecode field
234         // alike (AppDelegate+Menus.swift, where the items are built, used to
235         // state the opposite rule and now states this one).
236         //
237         // Worse than a swallowed keystroke: a scope change under an open
238         // field DISCARDS it. Entering leaves the renamed clip out of the
239         // snapshot the timeline is handed, so `relocateRename` ends the field
240         // with its commit dropped — the typing gone with no beep, no sheet
241         // and no undo step to find it in. The two GESTURES need no such
242         // guard: `beginGesture` opens with `endRename()`, so a double-click
243         // on a nest clip and a click on the breadcrumb both commit what is
244         // open before they act.
245         if view.window?.firstResponder is NSText,
246             action == #selector(openNest(_:)) || action == #selector(closeNest(_:))
247         {
248             return false
249         }
250         switch action {
251         case #selector(openNest(_:)):
252             return openableNestClip() != nil
253         case #selector(closeNest(_:)):
254             return !(document?.nestPath.isEmpty ?? true)
255         default:
256             return nil
257         }
258     }
