437     func validateTimelineAction(_ action: Selector) -> Bool? {
438         guard let document = document else { return false }
439         let hasSelection = !document.selection.isEmpty
440         switch action {
441         case #selector(duplicateClips(_:)), #selector(detachAudio(_:)):
442             return hasSelection
443         case #selector(attachAudio(_:)):
444             return selectedClips.contains { $0.linked != nil }
445         case #selector(deleteClips(_:)):
446             // ⌫ lifts the in/out range with nothing selected, so the item
447             // has to be live for that too.
448             //
449             // And it has to be DEAD while text is being edited, which is
450             // the guard AppDelegate's comment on this item asks for and
451             // which nothing supplied before: "\u{8}" is a modifier-less key
452             // equivalent, AppKit resolves those ahead of the first
453             // responder, and a live item therefore eats the Delete key in
454             // the timecode field, an inline rename and a text clip alike.
455             // The same test `handleEditorKey` opens with.
456             if view.window?.firstResponder is NSText { return false }
457             // And dead while the curve plot holds a selected point, whose ⌫
458             // deletes the point (spec §11 GR-12).
459             if (view.window?.firstResponder as? CurveEditorView)?.holdsDeleteKey == true {
460                 return false
461             }
462             if transcriptHoldsWords { return true }
463             return hasSelection || (document.inOutRange.map { $0.end > $0.start } ?? false)
464         case #selector(showSpeedSheet(_:)):
465             // `set_speed` is an ERROR on a non-media source (spec §6), so the
466             // item is live only when the selection holds something it can act
467             // on — the same subset `presentSpeedSheet` opens the sheet with.
468             return selectedClips.contains { $0.source.hasSourceBound }
469         case #selector(showSpeedRampSheet(_:)):
470             // Exactly one selected clip, and a media one: `add_speed_ramp`
471             // edits one clip and is an error on any other source (spec §11
472             // SR-24 (a)) — `presentSpeedRampSheet`'s own test.
473             return selectedClips.count == 1 && selectedClips[0].source.hasSourceBound
474         case #selector(rippleDeleteClips(_:)):
475             // The same guard as Delete: ⌘⌫ in a field editor is "delete to
476             // the start of the line", not a ripple delete of the selection —
477             // and the selected clip is the one whose rename field is open.
478             if view.window?.firstResponder is NSText { return false }
479             if transcriptHoldsWords { return true }
480             return hasSelection || (document.inOutRange.map { $0.end > $0.start } ?? false)
481         case #selector(trimStartToPlayhead(_:)), #selector(trimEndToPlayhead(_:)),
482             #selector(freezeFrame(_:)):
483             return !clipsUnderPlayhead.isEmpty
484         case #selector(splitAtPlayhead(_:)):
485             return !document.editedProject.snapshot.clips.isEmpty
486         case #selector(removeTrack(_:)), #selector(toggleTrackHidden(_:)),
487             #selector(toggleTrackMuted(_:)), #selector(toggleTrackLocked(_:)):
488             return currentTrack != nil
489         case #selector(nextMarker(_:)), #selector(previousMarker(_:)):
490             return !document.project.snapshot.markers.isEmpty
491         default:
492             return nil
493         }
